from __future__ import annotations

import base64
import json
import os
from typing import Any, Dict, List, Optional, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_receipt_bytes(receipt: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(receipt, (bytes, bytearray)):
        return bytes(receipt)

    if not isinstance(receipt, str):
        raise TypeError("receipt must be a file path, URL, bytes, or bytearray")

    if receipt.startswith(("http://", "https://")):
        import urllib.request

        with urllib.request.urlopen(receipt) as response:
            return response.read()

    if receipt.startswith("data:"):
        header, encoded = receipt.split(",", 1)
        return base64.b64decode(encoded)

    with open(receipt, "rb") as f:
        return f.read()


def _normalize_money(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, dict):
        for key in ("amount", "value", "gross", "net", "currencyValue"):
            if key in value:
                try:
                    return float(value[key])
                except (TypeError, ValueError):
                    pass
        return None
    try:
        return float(str(value).replace(",", "").strip())
    except (TypeError, ValueError):
        return None


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("value", "content"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return v
    if isinstance(field, dict):
        for key in ("value", "content", "text"):
            if key in field and field[key] is not None:
                return field[key]
    return field


def _extract_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    documents = getattr(result, "documents", None) or []
    for doc in documents:
        fields = getattr(doc, "fields", None) or {}
        line_items = fields.get("Items") or fields.get("items")
        if not line_items:
            continue

        items_value = _get_field_value(line_items)
        if not isinstance(items_value, list):
            continue

        for item in items_value:
            item_fields = getattr(item, "value_object", None) or getattr(item, "fields", None) or {}
            if isinstance(item_fields, dict):
                description = _get_field_value(item_fields.get("Description") or item_fields.get("Name"))
                quantity = _normalize_money(_get_field_value(item_fields.get("Quantity")))
                unit_price = _normalize_money(_get_field_value(item_fields.get("UnitPrice") or item_fields.get("Price")))
                amount = _normalize_money(_get_field_value(item_fields.get("Amount") or item_fields.get("TotalPrice")))
            else:
                description = None
                quantity = None
                unit_price = None
                amount = None

            items.append(
                {
                    "description": description,
                    "quantity": quantity,
                    "unit_price": unit_price,
                    "amount": amount,
                }
            )
    return items


def extract_receipt_data(receipt: Union[str, bytes, bytearray]) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    receipt_bytes = _read_receipt_bytes(receipt)

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=receipt_bytes,
        content_type="application/octet-stream",
    )
    result = poller.result()

    merchant = None
    tax = None
    total = None

    documents = getattr(result, "documents", None) or []
    for doc in documents:
        fields = getattr(doc, "fields", None) or {}
        merchant = merchant or _get_field_value(fields.get("MerchantName") or fields.get("VendorName") or fields.get("Merchant"))
        tax = tax if tax is not None else _normalize_money(_get_field_value(fields.get("TotalTax") or fields.get("Tax")))
        total = total if total is not None else _normalize_money(_get_field_value(fields.get("InvoiceTotal") or fields.get("Total")))

    if total is None:
        summary_fields = getattr(result, "documents", None) or []
        if summary_fields:
            fields = getattr(summary_fields[0], "fields", None) or {}
            total = _normalize_money(_get_field_value(fields.get("InvoiceTotal") or fields.get("Total")))

    items = _extract_items(result)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
